# Silic2 FPS Engine Makefile

# Platform detection
UNAME_S := $(shell uname -s 2>/dev/null)
ifeq ($(OS),Windows_NT)
    PLATFORM := windows
else ifeq ($(UNAME_S),Darwin)
    PLATFORM := macos
else
    PLATFORM := linux
endif

# Build configuration
BUILD ?= debug
VALID_BUILDS := debug release
ifeq ($(filter $(BUILD),$(VALID_BUILDS)),)
    $(error Unsupported BUILD '$(BUILD)'; expected one of: $(VALID_BUILDS))
endif

PLATFORM_BUILD_DIR := bin/$(PLATFORM)
BUILD_DIR := $(PLATFORM_BUILD_DIR)/$(BUILD)
OBJ_DIR := $(BUILD_DIR)/obj

COMMON_CXXFLAGS := -std=c++17 -Wall -Wextra
COMMON_CFLAGS := -Wall
ifeq ($(BUILD),release)
    CONFIG_FLAGS := -O2 -DNDEBUG
    TARGET_SUFFIX := -release
else
    CONFIG_FLAGS := -O0 -g3
    TARGET_SUFFIX :=
endif

CXXFLAGS := $(COMMON_CXXFLAGS) $(CONFIG_FLAGS)
CFLAGS := $(COMMON_CFLAGS) $(CONFIG_FLAGS)
DEPFLAGS := -MMD -MP

INCLUDES := -I./include \
            -I./include/glad \
            -I./include/GLFW \
            -I./include/glm \
            -I./include/stb

# Set CACHE=ccache (or CACHE=sccache) to enable a compiler cache without
# changing the selected platform compiler.
CACHE ?=

ifeq ($(PLATFORM),windows)
    CXX = $(CACHE) g++
    CC = $(CACHE) gcc
    LDFLAGS := -L./lib
    LIBS := -lglfw3 -lopengl32 -lgdi32 -luser32 -lkernel32
    APP_TARGET := silic2$(TARGET_SUFFIX).exe
    define make-dir
	@if not exist "$(subst /,\,$@)" mkdir "$(subst /,\,$@)"
    endef
    CLEAN_CMD = if exist "$(subst /,\,$(BUILD_DIR))" rmdir /S /Q "$(subst /,\,$(BUILD_DIR))" & if exist "$(APP_TARGET)" del /Q "$(APP_TARGET)"
else ifeq ($(PLATFORM),macos)
    CXX = $(CACHE) clang++
    CC = $(CACHE) clang
    INCLUDES += -I/opt/homebrew/include -I/usr/local/include
    LDFLAGS := -L/opt/homebrew/lib -L/usr/local/lib
    LIBS := -lglfw -framework OpenGL -framework Cocoa -framework IOKit -framework CoreVideo -framework CoreAudio -framework AudioToolbox
    APP_TARGET := silic2$(TARGET_SUFFIX)
    define make-dir
	@mkdir -p "$@"
    endef
    CLEAN_CMD = rm -rf "$(BUILD_DIR)" "$(APP_TARGET)"
else
    CXX = $(CACHE) g++
    CC = $(CACHE) gcc
    LDFLAGS := -L/usr/local/lib -L./lib
    LIBS := -lglfw -lGL -ldl -lpthread -lm
    APP_TARGET := silic2$(TARGET_SUFFIX)
    define make-dir
	@mkdir -p "$@"
    endef
    CLEAN_CMD = rm -rf "$(BUILD_DIR)" "$(APP_TARGET)"
endif

# Keep full source paths so files with the same basename can coexist in
# different modules without object-file collisions.
ENGINE_SRCS := src/engine/main.cpp \
               src/engine/app.cpp src/engine/app_crystal.cpp \
               src/engine/camera.cpp \
               src/engine/collision.cpp \
               src/engine/shader.cpp \
               src/engine/texture.cpp \
               src/engine/map.cpp \
               src/engine/mesh_asset.cpp \
               src/engine/spatial_world.cpp \
               src/engine/map_renderer.cpp \
               src/engine/pixel_renderer.cpp \
               src/engine/fisheye_settings.cpp \
               src/engine/simple_json.cpp \
               src/engine/game_config.cpp

ENGINE_C_SRCS := src/engine/glad.c

PLAYER_SRCS := src/player/player.cpp \
               src/player/weapon.cpp

ENEMY_SRCS := src/enemy/enemy.cpp src/enemy/crystal_enemy.cpp \
              src/enemy/enemy_manager.cpp \
              src/enemy/enemy_projectile_system.cpp

EFFECTS_SRCS := src/effects/particle_system.cpp \
                src/effects/groundparticle.cpp

HUD_SRCS := src/hud/crosshair.cpp \
            src/hud/minimap.cpp \
            src/hud/hud_renderer.cpp \
            src/hud/bitmap_font_renderer.cpp \
            src/hud/hud_view_model.cpp

GAME_SRCS := src/game/seed_service.cpp \
             src/game/run_stats.cpp \
             src/game/run_controller.cpp \
             src/game/arena_definition.cpp \
             src/game/encounter_director.cpp \
             src/game/exploration_controller.cpp

PRESENTATION_SRCS := src/character/crystal_creatures.cpp src/environment/environment_scene.cpp src/environment/environment_renderer.cpp src/character/character_presentation.cpp src/character/imported_weapon.cpp src/character/weapon_asset.cpp src/character/procedural_rifle.cpp src/audio/audio_system.cpp src/audio/miniaudio_impl.cpp

CPP_SRCS := $(ENGINE_SRCS) $(PLAYER_SRCS) $(ENEMY_SRCS) $(EFFECTS_SRCS) $(HUD_SRCS) $(GAME_SRCS) $(PRESENTATION_SRCS)
C_SRCS := $(ENGINE_C_SRCS)
CPP_OBJS := $(patsubst src/%.cpp,$(OBJ_DIR)/%.o,$(CPP_SRCS))
C_OBJS := $(patsubst src/%.c,$(OBJ_DIR)/%.o,$(C_SRCS))
APP_OBJS := $(CPP_OBJS) $(C_OBJS)

TEST_SRCS := tests/test_main.cpp \
             tests/camera_lean_test.cpp \
             tests/simple_json_test.cpp \
             tests/map_test.cpp \
             tests/map_navigation_test.cpp \
             tests/seed_service_test.cpp \
             tests/run_stats_test.cpp \
             tests/run_controller_test.cpp \
             tests/enemy_ground_test.cpp \
             tests/encounter_director_test.cpp \
             tests/exploration_test.cpp \
             tests/spatial_world_test.cpp \
             tests/enemy_combat_test.cpp \
             tests/audio_system_test.cpp \
             tests/hud_view_model_test.cpp \
             tests/player_damage_test.cpp \
             tests/player_roll_test.cpp
TEST_OBJS := $(patsubst tests/%.cpp,$(OBJ_DIR)/tests/%.o,$(TEST_SRCS))
GAME_OBJS := $(patsubst src/%.cpp,$(OBJ_DIR)/%.o,$(GAME_SRCS))
TEST_SUPPORT_SRCS := src/player/player.cpp src/engine/camera.cpp src/engine/game_config.cpp \
                     src/hud/bitmap_font_renderer.cpp src/hud/hud_view_model.cpp \
                     src/enemy/enemy_projectile_system.cpp src/enemy/enemy_manager.cpp src/engine/shader.cpp \
                     src/audio/audio_system.cpp \
                     src/audio/miniaudio_impl.cpp \
                     src/enemy/enemy.cpp src/enemy/crystal_enemy.cpp \
                     src/engine/map.cpp \
                     src/engine/mesh_asset.cpp \
                     src/engine/spatial_world.cpp \
                     src/engine/simple_json.cpp \
                     src/engine/collision.cpp
TEST_SUPPORT_OBJS := $(patsubst src/%.cpp,$(OBJ_DIR)/%.o,$(TEST_SUPPORT_SRCS)) $(OBJ_DIR)/engine/glad.o
TEST_TARGET := $(BUILD_DIR)/silic2-tests$(if $(filter windows,$(PLATFORM)),.exe,)

HORROR_PREVIEW_OBJ := $(OBJ_DIR)/tests/horror_scene_preview.o
HORROR_PREVIEW_TARGET := $(BUILD_DIR)/horror-scene-preview$(if $(filter windows,$(PLATFORM)),.exe,)

SPATIAL_PROBE_OBJ := $(OBJ_DIR)/tests/spatial_combat_probe.o
SPATIAL_PROBE_TARGET := $(BUILD_DIR)/spatial-combat-probe
ALL_OBJS := $(APP_OBJS) $(TEST_OBJS) $(HORROR_PREVIEW_OBJ) $(SPATIAL_PROBE_OBJ)
DEPS := $(ALL_OBJS:.o=.d)
OBJ_DIRS := $(sort $(patsubst %/,%,$(dir $(ALL_OBJS))))

# Default target
all: $(APP_TARGET)

# Link
$(APP_TARGET): $(APP_OBJS)
	$(CXX) $(APP_OBJS) -o $@ $(LDFLAGS) $(LIBS)

# Compile C++ and C sources. Each compiler also writes a matching .d file so
# header changes rebuild exactly the translation units that include them.
$(ALL_OBJS): | $(OBJ_DIRS)

$(OBJ_DIRS):
	$(make-dir)

$(OBJ_DIR)/%.o: src/%.cpp
	$(CXX) $(CXXFLAGS) $(DEPFLAGS) $(INCLUDES) -c $< -o $@

$(OBJ_DIR)/%.o: src/%.c
	$(CC) $(CFLAGS) $(DEPFLAGS) $(INCLUDES) -c $< -o $@

$(OBJ_DIR)/tests/%.o: tests/%.cpp
	$(CXX) $(CXXFLAGS) $(DEPFLAGS) $(INCLUDES) -I./tests -c $< -o $@

-include $(DEPS)

$(TEST_TARGET): $(TEST_OBJS) $(GAME_OBJS) $(TEST_SUPPORT_OBJS)
	$(CXX) $(TEST_OBJS) $(GAME_OBJS) $(TEST_SUPPORT_OBJS) -o $@ $(LDFLAGS) $(LIBS)

test: $(TEST_TARGET)
	./$(TEST_TARGET)

# Opt-in synthetic GL capture; building this target never opens a window.
$(HORROR_PREVIEW_TARGET): $(HORROR_PREVIEW_OBJ) $(filter-out $(OBJ_DIR)/engine/main.o $(OBJ_DIR)/engine/app.o $(OBJ_DIR)/engine/app_crystal.o,$(APP_OBJS))
	$(CXX) $^ -o $@ $(LDFLAGS) $(LIBS)

horror-preview: $(HORROR_PREVIEW_TARGET)

CRYSTAL_POSE_OBJ := $(OBJ_DIR)/character/preview/crystal_creature_check.o
CRYSTAL_POSE_TARGET := $(BUILD_DIR)/crystal-creature-check$(if $(filter windows,$(PLATFORM)),.exe,)
$(CRYSTAL_POSE_OBJ): | $(OBJ_DIR)/character/preview
$(OBJ_DIR)/character/preview:
	$(make-dir)
-include $(CRYSTAL_POSE_OBJ:.o=.d)
$(CRYSTAL_POSE_TARGET): $(CRYSTAL_POSE_OBJ) $(filter-out $(OBJ_DIR)/engine/main.o $(OBJ_DIR)/engine/app.o $(OBJ_DIR)/engine/app_crystal.o,$(APP_OBJS))
	$(CXX) $^ -o $@ $(LDFLAGS) $(LIBS)
crystal-creature-check: $(CRYSTAL_POSE_TARGET)
.PHONY: crystal-creature-check

# Convenience configuration targets
debug:
	$(MAKE) -f $(firstword $(MAKEFILE_LIST)) BUILD=debug all

release:
	$(MAKE) -f $(firstword $(MAKEFILE_LIST)) BUILD=release all

run: $(APP_TARGET)
	./$(APP_TARGET)

run-release:
	$(MAKE) -f $(firstword $(MAKEFILE_LIST)) BUILD=release run

# Map shortcuts; default launch remains Hollow Orbit.
hollow-orbit: $(APP_TARGET)
	./$(APP_TARGET) res/maps/hollow_orbit_arena.json

starry-crystal: $(APP_TARGET)
	./$(APP_TARGET) res/maps/starry_crystal_arena.json

# Legacy map shortcuts
test-room: $(APP_TARGET)
	./$(APP_TARGET) res/maps/test_room.json

corridor: $(APP_TARGET)
	./$(APP_TARGET) res/maps/simple_corridor.json

textured-room: $(APP_TARGET)
	./$(APP_TARGET) res/maps/textured_room.json

print-config:
	@echo Platform: $(PLATFORM)
	@echo Build: $(BUILD)
	@echo Compiler: $(CXX)
	@echo Object directory: $(OBJ_DIR)
	@echo Target: $(APP_TARGET)

clean:
	$(CLEAN_CMD)

.PHONY: hollow-orbit starry-crystal horror-preview all debug release run run-release test test-room corridor textured-room print-config clean

$(SPATIAL_PROBE_TARGET): $(SPATIAL_PROBE_OBJ) $(GAME_OBJS) $(TEST_SUPPORT_OBJS)
	$(CXX) $^ -o $@ $(LDFLAGS) $(LIBS)

spatial-probe: $(SPATIAL_PROBE_TARGET)

.PHONY: spatial-probe

# Offline static import checks: real temporary GLBs -> OBJ -> actual CPU engine loader.
# No OpenGL context, Tripo request, account credentials, or generated art required.
ASSET_CHECK_TARGET := $(BUILD_DIR)/verify-static-bundle
$(ASSET_CHECK_TARGET): tools/assets/verify_bundle.cpp $(OBJ_DIR)/engine/mesh_asset.o $(OBJ_DIR)/engine/simple_json.o
	$(CXX) $(CXXFLAGS) $(INCLUDES) $^ -o $@

asset-import-test: $(ASSET_CHECK_TARGET)
	SILIC2_BUNDLE_CHECK="$(abspath $(ASSET_CHECK_TARGET))" python3 -m unittest discover -s tools/assets -p 'test_*.py' -v

.PHONY: asset-import-test

# Actual imported interior cover/proxy validation, CPU only (assets stay local).
INTERIOR_PROBE_OBJ := $(OBJ_DIR)/tests/interior_collision_probe.o
INTERIOR_PROBE_TARGET := $(BUILD_DIR)/interior-collision-probe
$(INTERIOR_PROBE_OBJ): | $(OBJ_DIR)/tests
-include $(INTERIOR_PROBE_OBJ:.o=.d)
$(INTERIOR_PROBE_TARGET): $(INTERIOR_PROBE_OBJ) $(GAME_OBJS) $(TEST_SUPPORT_OBJS)
	$(CXX) $^ -o $@ $(LDFLAGS) $(LIBS)
interior-probe: $(INTERIOR_PROBE_TARGET)
.PHONY: interior-probe

# Authored giant-wall collision and near-wall movement, without performance sampling.
MEGA_PROBE_OBJ := $(OBJ_DIR)/tests/mega_structure_probe.o
MEGA_PROBE_TARGET := $(BUILD_DIR)/mega-structure-probe
$(MEGA_PROBE_OBJ): | $(OBJ_DIR)/tests
-include $(MEGA_PROBE_OBJ:.o=.d)
$(MEGA_PROBE_TARGET): $(MEGA_PROBE_OBJ) $(GAME_OBJS) $(TEST_SUPPORT_OBJS)
	$(CXX) $^ -o $@ $(LDFLAGS) $(LIBS)
mega-probe: $(MEGA_PROBE_TARGET)
.PHONY: mega-probe

# Forest large-map traversal/contact checks; no performance sampling.
FOREST_PROBE_OBJ := $(OBJ_DIR)/tests/forest_arena_probe.o
FOREST_PROBE_TARGET := $(BUILD_DIR)/forest-arena-probe
$(FOREST_PROBE_OBJ): | $(OBJ_DIR)/tests
-include $(FOREST_PROBE_OBJ:.o=.d)
$(FOREST_PROBE_TARGET): $(FOREST_PROBE_OBJ) $(GAME_OBJS) $(TEST_SUPPORT_OBJS)
	$(CXX) $^ -o $@ $(LDFLAGS) $(LIBS)
forest-probe: $(FOREST_PROBE_TARGET)
.PHONY: forest-probe

# Functional transparency/occlusion/state checks; requires a serial GPU slot.
FOREST_GL_CHECK_OBJ := $(OBJ_DIR)/tests/forest_translucency_check.o
FOREST_GL_CHECK_TARGET := $(BUILD_DIR)/forest-translucency-check
$(FOREST_GL_CHECK_OBJ): | $(OBJ_DIR)/tests
-include $(FOREST_GL_CHECK_OBJ:.o=.d)
$(FOREST_GL_CHECK_TARGET): $(FOREST_GL_CHECK_OBJ) $(filter-out $(OBJ_DIR)/engine/main.o $(OBJ_DIR)/engine/app.o $(OBJ_DIR)/engine/app_crystal.o,$(APP_OBJS))
	$(CXX) $^ -o $@ $(LDFLAGS) $(LIBS)
forest-translucency-check: $(FOREST_GL_CHECK_TARGET)
.PHONY: forest-translucency-check

# Short frozen-scene diagnosis; explicit invocation only, no stress benchmark.
FOREST_RENDER_PROBE_OBJ := $(OBJ_DIR)/tests/forest_render_probe.o
FOREST_RENDER_PROBE_TARGET := $(BUILD_DIR)/forest-render-probe
$(FOREST_RENDER_PROBE_OBJ): | $(OBJ_DIR)/tests
-include $(FOREST_RENDER_PROBE_OBJ:.o=.d)
$(FOREST_RENDER_PROBE_TARGET): $(FOREST_RENDER_PROBE_OBJ) $(filter-out $(OBJ_DIR)/engine/main.o $(OBJ_DIR)/engine/app.o $(OBJ_DIR)/engine/app_crystal.o,$(APP_OBJS))
	$(CXX) $^ -o $@ $(LDFLAGS) $(LIBS)
forest-render-probe: $(FOREST_RENDER_PROBE_TARGET)
.PHONY: forest-render-probe

# ADS behavior integration without a GL context (actual Player/Weapon/HUD paths).
ADS_CHECK_OBJ := $(OBJ_DIR)/tests/aim_state_test.o
ADS_CHECK_TARGET := $(BUILD_DIR)/aim-state-check
$(ADS_CHECK_OBJ): | $(OBJ_DIR)/tests
-include $(ADS_CHECK_OBJ:.o=.d)
$(ADS_CHECK_TARGET): $(ADS_CHECK_OBJ) $(filter-out $(OBJ_DIR)/engine/main.o $(OBJ_DIR)/engine/app.o $(OBJ_DIR)/engine/app_crystal.o,$(APP_OBJS))
	$(CXX) $^ -o $@ $(LDFLAGS) $(LIBS)
ads-check: $(ADS_CHECK_TARGET)
	./$(ADS_CHECK_TARGET)
.PHONY: ads-check

# Actual procedural rifle CPU geometry/asset contract, without a GL context.
PROCEDURAL_RIFLE_CHECK_OBJ := $(OBJ_DIR)/tests/procedural_rifle_test.o
PROCEDURAL_RIFLE_CHECK_TARGET := $(BUILD_DIR)/procedural-rifle-check
$(PROCEDURAL_RIFLE_CHECK_OBJ): | $(OBJ_DIR)/tests
-include $(PROCEDURAL_RIFLE_CHECK_OBJ:.o=.d)
$(PROCEDURAL_RIFLE_CHECK_TARGET): $(PROCEDURAL_RIFLE_CHECK_OBJ) $(OBJ_DIR)/character/procedural_rifle.o $(OBJ_DIR)/character/weapon_asset.o $(OBJ_DIR)/engine/mesh_asset.o $(OBJ_DIR)/engine/simple_json.o
	$(CXX) $^ -o $@ $(LDFLAGS) $(LIBS)
procedural-rifle-check: $(PROCEDURAL_RIFLE_CHECK_TARGET)
	./$(PROCEDURAL_RIFLE_CHECK_TARGET)
.PHONY: procedural-rifle-check

# Forest player self-emission lifecycle, CPU only; no GL context needed.
PLAYER_AURA_CHECK_OBJ := $(OBJ_DIR)/tests/player_aura_test.o
PLAYER_AURA_CHECK_TARGET := $(BUILD_DIR)/player-aura-check
$(PLAYER_AURA_CHECK_OBJ): | $(OBJ_DIR)/tests
-include $(PLAYER_AURA_CHECK_OBJ:.o=.d)
$(PLAYER_AURA_CHECK_TARGET): $(PLAYER_AURA_CHECK_OBJ) $(filter-out $(OBJ_DIR)/engine/main.o $(OBJ_DIR)/engine/app.o $(OBJ_DIR)/engine/app_crystal.o,$(APP_OBJS))
	$(CXX) $^ -o $@ $(LDFLAGS) $(LIBS)
player-aura-check: $(PLAYER_AURA_CHECK_TARGET)
	./$(PLAYER_AURA_CHECK_TARGET)
.PHONY: player-aura-check
